  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Hydroxysafflor yellow A, a highly polar polyhydroxylated glycoside, reached 1026 ng/g in rat brain, demonstrating that polar polyphenolic compounds can achieve measurable CNS exposure; this transfers to the caffeoylquinic acid query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A cinnamoyl-containing N-benzoylindole derivative showed 2.00% ID/g initial brain uptake in mice, supporting that the cinnamoyl scaffold present in the query can confer brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Bisdemethoxycurcumin, a cinnamoyl-containing polyphenol, reached a mean brain concentration of 20 ng/g after oral dosing and was considered sufficiently available across the BBB, supporting CNS access for related cinnamoyl polyphenols.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "A fluorinated curcumin analogue showed 5.47% ID/g brain uptake at 2 min in mice with favorable BBB permeability, providing additional transferable evidence that cinnamoyl-based compounds can access the brain.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted pass: multiple high-transfer experimental records demonstrate brain uptake or BBB penetration for cinnamoyl-containing and polar polyphenolic analogues, including a highly polar glycoside reaching 1026 ng/g in rat brain; no contradictory evidence was provided.",
  "evidence_gaps": [
    "No direct brain or plasma pharmacokinetic measurement for chlorogenic acid itself.",
    "Most supportive analogues are more lipophilic than the query and lack the quinic acid/carboxylate moiety.",
    "Brain concentrations in some records are low and dose/plasma ratios are not reported, making the degree of 'meaningful' access uncertain.",
    "Efflux transporter liability for the query was not directly assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

